// Where each component stands on iOS and Android, from the native libraries' own lists
// (native-components.ts, generated by `bun run native`): what a component page's masthead and its
// Platforms section show, and the Platforms page's matrix.
import { slug } from "../docs/components";
import {
  androidComponents,
  androidNotBuilt,
  iosComponents,
  type NativeComponent,
} from "../native-components";

export type { NativeComponent };

// A component the native list names twice (Android's copy button, under Actions and Data display) is one.
const once = (list: NativeComponent[]) =>
  list.filter((c, i) => list.findIndex((o) => o.name === c.name && o.api[0] === c.api[0]) === i);
export const ios = once(iosComponents);
export const android = once(androidComponents);

/** A web page's native counterparts, in the native lists' order. */
export const nativeOf = (page: string) => ({
  ios: ios.filter((c) => c.pages.includes(page)),
  android: android.filter((c) => c.pages.includes(page)),
});

// "a navigation drawer, a popover, a toast, a data table and image presentation": each phrase's last word.
const leftOut = androidNotBuilt.split(/, | and /).map((phrase) => phrase.split(" ").at(-1) ?? "");
/** Whether Qeetrix for Android leaves this component out on purpose, as its list says. */
export const leftOutOnAndroid = (name: string) => leftOut.includes(name.toLowerCase());

export interface NativeOnly {
  name: string;
  ios?: NativeComponent;
  android?: NativeComponent;
  /** The @qeetrix/react names either list gives as its counterpart. */
  web: string[];
}

/**
 * The native components no web page covers, one row each: iOS's and Android's together where they share
 * a name or an API ("OTP code" and "One-time code" are both QeetrixOTPCode), with the other platform's
 * component filled in even where that one has a page.
 */
export const nativeOnly: NativeOnly[] = (() => {
  const same = (a: NativeComponent, b: NativeComponent) =>
    slug(a.name) === slug(b.name) || a.api[0] === b.api[0];
  const rows: NativeOnly[] = [];
  for (const c of [...ios, ...android].filter((n) => n.pages.length === 0)) {
    if (rows.some((r) => (r.ios && same(r.ios, c)) || (r.android && same(r.android, c)))) continue;
    const i = ios.find((n) => same(n, c));
    const a = android.find((n) => same(n, c));
    rows.push({
      name: c.name,
      ios: i,
      android: a,
      web: [...new Set([...(i?.web ?? []), ...(a?.web ?? [])])],
    });
  }
  return rows;
})();
